      "ballot_id": "B020",
      "proposed_laureates": [
        "Alexei Kitaev",
        "Andrew M. Steane",
        "Peter W. Shor"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction showed that quantum information can be protected despite decoherence, changing quantum computing from a fragile ideal into a physically addressable program.",
        "attribution": "Shor and Steane independently introduced seminal quantum codes, while Kitaev's topological code and fault-tolerance work supplied a distinct influential framework.",
        "maturity": "The theory is established and experimental demonstrations have advanced substantially, though large-scale fault-tolerant operation remains an engineering and physics challenge.",
        "uncertainties": [
          "The field's foundational contributions extend beyond these three names, so a sharply bounded prize citation would need care."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B008",
      "proposed_laureates": [
        "Michel Della Negra",
        "Peter Jenni",
        "Tejinder S. Virdee"
      ],
      "assessment": {
        "nobel_worthiness": "The ATLAS and CMS discovery established the Higgs boson and completed a major prediction of the Standard Model, an exceptionally consequential experimental achievement.",
        "attribution": "These leaders represent the two collaborations and their long experimental programs; the discovery depended on thousands of researchers and the accelerator teams.",
        "maturity": "The particle has been confirmed and its properties measured over many years, making the discovery fully mature.",
        "uncertainties": [
          "The Nobel's individual laureate limit cannot represent the scale of the collaborations or all essential technical contributions."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B001",
      "proposed_laureates": [
        "Alexander Polyakov",
        "Edward Witten",
        "Juan Maldacena"
      ],
      "assessment": {
        "nobel_worthiness": "Gauge/gravity duality is a profound connection between quantum field theory and gravity that has reshaped work across high-energy theory, quantum gravity, and strongly interacting matter.",
        "attribution": "Maldacena's precise duality proposal was pivotal; Polyakov and Witten made foundational contributions to the underlying string and gauge theory ideas and their development.",
        "maturity": "The duality has generated extensive theoretical results and applications, though its physical interpretation and direct empirical status remain unsettled.",
        "uncertainties": [
          "The connection is strongly supported mathematically but lacks direct experimental confirmation as a description of nature."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B005",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks combine precision measurement with a robust atomic reference and have opened new tests of fundamental physics and practical timekeeping.",
        "attribution": "Katori and Ye independently pioneered complementary clock approaches, with clear and well-established individual contributions.",
        "maturity": "The technology has been demonstrated and refined over decades, with impressive accuracy and increasing real-world relevance.",
        "uncertainties": [
          "The ultimate scope of their impact on time standards and fundamental tests is still developing."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B022",
      "proposed_laureates": [
        "Charles L. Kane",
        "Eugene J. Mele",
        "Laurens W. Molenkamp"
      ],
      "assessment": {
        "nobel_worthiness": "The prediction and experimental realization of quantum spin Hall and topological insulator phases established a major framework for classifying and studying quantum matter.",
        "attribution": "Kane and Mele supplied seminal theory, and Molenkamp's experiments provided an early decisive realization. These roles form a compelling theory-experiment citation.",
        "maturity": "The phases are well established and the work has had broad influence, although proposed applications have been less decisive than the foundational physics.",
        "uncertainties": [
          "The discovery's boundaries overlap with later topological materials work and other candidate formulations."
        ]
      }
    },
